<?php require __DIR__.'/config.php';$admin=require_admin();method_is('PATCH');$d=body_json();$id=(int)($d['order_id']??0);$status=(string)($d['status']??'');if($id<1||!in_array($status,['Paid','Failed'],true))json_out(['error'=>'Invalid payment update.'],422);$s=$pdo->prepare('SELECT id,method,status FROM payments WHERE order_id=? ORDER BY id DESC LIMIT 1');$s->execute([$id]);$p=$s->fetch();if(!$p||$p['method']==='Cash')json_out(['error'=>'No online payment to verify.'],422);if($status==='Paid'&&empty($p['gateway_reference']))json_out(['error'=>'A submitted reference number is required before confirming payment.'],422);$s=$pdo->prepare('UPDATE payments SET status=?,verified_by=?,verified_at=NOW() WHERE id=?');$s->execute([$status,$admin['id'],$p['id']]);json_out(['ok'=>true]);?>